+size_t ReadManager::splitIntoLanes(RowGroup & row_group)
+{
+    const size_t num_subgroups = row_group.subgroups.size();
+    if (num_subgroups < 2 || !row_group.need_to_process)
+        return 1;
+
+    /// The lanes deliver the subgroups of a row group out of order, and each lane reads every column
+    /// chunk with a cursor of its own (sharing only the prefetched bytes of the whole chunk). Keep one
+    /// lane where the order or other per-row-group state matters: per-page prefetches (offset index),
+    /// which the reading task releases, the columns cache, top-K bookkeeping, lazy materialization,
+    /// read-ahead of remote reads, and arrays, whose rows the cursor can't skip by page headers.
+    if (reader.options.format.parquet.preserve_order
+        || (reader.format_filter_info && reader.format_filter_info->rows_to_read)
+        || reader.row_groups_ordered_by_top_k
+        || reader.top_k_best_value_column_pos.has_value()
+        || column_data_read_ahead
+        || !row_group.cached_columns.empty()
+        || !row_group.columns_cache_writes.empty())
+        return 1;
+    for (size_t i = 0; i < row_group.columns.size(); ++i)
+    {
+        const ColumnChunk & column = row_group.columns[i];
+        if (!column.data_pages.empty() || column.offset_index_prefetch || !column.offset_index.page_locations.empty()
+            || column.served_from_cache || reader.primitive_columns.at(i).levels.back().rep > 0)
+            return 1;
+    }
+
+    /// A lane adds parallelism only while one subgroup can't keep the reader's column data threads busy.
+    /// The column tasks of a step run in parallel, so its most expensive step can use about as many threads
+    /// as its columns' bytes over the bytes of the largest one: several for `SELECT *`, about one for a query
+    /// that decodes one string column under a filter. See `tryAddLanes`.
+    {
+        std::vector<size_t> step_bytes(reader.steps.size() + 1, 0);
+        std::vector<size_t> step_max(reader.steps.size() + 1, 0);
+        for (size_t i = 0; i < row_group.columns.size(); ++i)
+        {
+            size_t step = reader.primitive_columns.at(i).first_step_to_calculate;
+            if (step >= step_bytes.size())
+                continue;
+            size_t bytes = size_t(std::max<Int64>(0, row_group.columns[i].meta->meta_data.total_uncompressed_size));
+            step_bytes[step] += bytes;
+            step_max[step] = std::max(step_max[step], bytes);
+        }
+        size_t dominant = size_t(std::max_element(step_bytes.begin(), step_bytes.end()) - step_bytes.begin());
+        row_group.lanes_parallel_tasks = step_max[dominant] ? double(step_bytes[dominant]) / double(step_max[dominant]) : 1.;
+    }
+
+    /// Lanes are for a block that keeps about one thread busy. A block whose most expensive step can already
+    /// use two threads (a wide read) gets none, however many threads the query has: a lane would decode the
+    /// dictionaries of all its columns again and hold one more block.
+    if (row_group.lanes_parallel_tasks >= 2.)
+        return 1;
+
+    /// At most the column data threads of the reader as if it were the only one: the per-reader limit
+    /// divides them by the readers of the query, but in a glob of files most readers are often pruned
+    /// or done early, and the limit grows as they finish. Lanes are added only while it allows.
+    /// And at most `max_lanes` (the share at 16 threads), so that the extra memory of a row group, a block and
+    /// the dictionaries per lane, stays the same with more threads.
+    static constexpr size_t max_lanes = 4;
+    const double fraction = stages[size_t(ReadStage::ColumnData)].memory_target_fraction;
+    const size_t threads = size_t(std::max(
+        std::lround(static_cast<double>(parser_shared_resources->parsing_runner.getMaxThreads()) * fraction + .5), 1l));
+    const size_t num_lanes = std::min({num_subgroups, threads, max_lanes});
+    if (num_lanes < 2)
+        return 1;
+
+    row_group.lanes_mutex = std::make_unique<std::mutex>();
+    row_group.next_subgroup.store(0, std::memory_order_relaxed);
+    row_group.subgroups_to_read.store(num_subgroups, std::memory_order_relaxed);
+    for (auto & column : row_group.columns)
+        column.lane_shared_pages = std::make_shared<Reader::LaneSharedPages>();
+    row_group.lane_columns.resize(num_lanes - 1);
+    for (auto & lane_columns : row_group.lane_columns)
+    {
+        lane_columns.resize(row_group.columns.size());
+        for (size_t i = 0; i < row_group.columns.size(); ++i)
+        {
+            ColumnChunk & owner = row_group.columns[i];
+            ColumnChunk & lane_column = lane_columns[i];
+            lane_column.lane_shared_pages = owner.lane_shared_pages;
+            lane_column.meta = owner.meta;
+            lane_column.need_null_map = owner.need_null_map;
+            lane_column.data_pages_bytes = owner.data_pages_bytes;
+            lane_column.stage = owner.stage;
+            lane_column.lane_owner = &owner;
+        }
+    }
+    row_group.num_lanes = num_lanes;
+    return num_lanes;
+}
