+bool ReadManager::takeSubgroupForLane(size_t row_group_idx, size_t lane, MemoryUsageDiff & diff)
+{
+    RowGroup & row_group = reader.row_groups[row_group_idx];
+    while (true)
+    {
+        size_t row_subgroup_idx = row_group.next_subgroup.fetch_add(1);
+        if (row_subgroup_idx >= row_group.subgroups.size())
+            return false;
+        RowSubgroup & row_subgroup = row_group.subgroups[row_subgroup_idx];
+        row_subgroup.lane = lane;
+        if (row_subgroup.filter.rows_pass > 0)
+        {
+            size_t first_step = reader.steps.empty() ? 0 : 1;
+            addTasksToReadColumns(row_group_idx, row_subgroup_idx, ReadStage::OffsetIndex, first_step, diff);
+            return true;
+        }
+        /// Nothing to read in this subgroup.
+        row_subgroup.stage.store(ReadStage::Deallocated);
+        clearRowSubgroup(row_subgroup, diff);
+        finishSubgroupInLane(row_group_idx, row_subgroup_idx, /*filtered_out=*/ true, diff, /*take_next=*/ false);
+    }
+}
+
+void ReadManager::tryAddLanes(size_t row_group_idx, MemoryUsageDiff & diff)
+{
+    RowGroup & row_group = reader.row_groups[row_group_idx];
+    const Stage & stage = stages[size_t(ReadStage::ColumnData)];
+    while (row_group.active_lanes.load() < row_group.num_lanes
+        && row_group.next_subgroup.load() < row_group.subgroups.size())
+    {
+        /// A lane costs its own decoding of the dictionaries, so add it only for threads that would
+        /// otherwise be idle: the reader's current column data thread limit is not taken by the tasks
+        /// in progress and the groups of tasks waiting to be scheduled.
+        auto limits = SharedResourcesExt::getLimitsPerReader(*parser_shared_resources, stage.memory_target_fraction);
+        if (row_group.lanes_parallel_tasks >= double(limits.parsing_threads))
+            return;
+        size_t busy = stage.batches_in_progress.load(std::memory_order_relaxed);
+        for (auto i = stage.schedulable_row_groups.findFirst(); i.has_value() && busy < limits.parsing_threads; i = stage.schedulable_row_groups.findNext(*i + 1))
+            busy += 1;
+        if (busy >= limits.parsing_threads)
+            return;
+        size_t lane = row_group.active_lanes.fetch_add(1);
+        if (lane >= row_group.num_lanes)
+        {
+            row_group.active_lanes.fetch_sub(1);
+            return;
+        }
+        if (lane == 1)
+            ProfileEvents::increment(ProfileEvents::ParquetRowGroupsReadInLanes);
+        if (!takeSubgroupForLane(row_group_idx, lane, diff))
+            return;
+    }
+}
+
+void ReadManager::finishSubgroupInLane(size_t row_group_idx, size_t row_subgroup_idx, bool filtered_out, MemoryUsageDiff & diff, bool take_next)
+{
+    RowGroup & row_group = reader.row_groups[row_group_idx];
+    RowSubgroup & row_subgroup = row_group.subgroups[row_subgroup_idx];
+    const size_t lane = row_subgroup.lane;
+    if (filtered_out && take_next)
+    {
+        /// Filtered out by PREWHERE.
+        row_subgroup.stage.store(ReadStage::Deallocated);
+        clearRowSubgroup(row_subgroup, diff);
+    }
+    advanceDeliveryPtrIfNeeded(row_group_idx, diff);
+
+    if (row_group.subgroups_to_read.fetch_sub(1) == 1)
+    {
+        /// All subgroups are read (not necessarily delivered), see the end of finishRowSubgroupStage.
+        /// The column chunks of the other lanes go first: the first lane's ones hold their prefetches.
+        for (auto & lane_columns : row_group.lane_columns)
+            for (auto & lane_column : lane_columns)
+                clearColumnChunk(lane_column, diff);
+        for (size_t i = 0; i < reader.primitive_columns.size(); ++i)
+            clearColumnChunk(row_group.columns.at(i), diff);
+        reader.flushColumnsCacheWrites(row_group);
+        releaseTopKAdmission(row_group_idx, diff);
+        return;
+    }
+
+    if (take_next)
+    {
+        takeSubgroupForLane(row_group_idx, lane, diff);
+        tryAddLanes(row_group_idx, diff);
+    }
+}
