--- /dev/null
+++ b/tests/queries/0_stateless/05488_statistics_union_all_constant_column_estimate.sql
@@ -0,0 +1,50 @@
+-- Tags: no-random-merge-tree-settings
+-- A filter on a constant column of UNION ALL branches reaches each branch as `materialize(<constant>) = <constant>`.
+-- The estimator must not count it as a selective condition: a read in the selected branch keeps the row estimate it
+-- has without it, and a branch the constant rules out is estimated empty.
+
+SET enable_analyzer = 1;
+SET use_statistics = 1;
+SET query_plan_optimize_join_order_limit = 10;
+SET query_plan_join_swap_table = 'auto';
+SET enable_join_runtime_filters = 0;
+SET enable_parallel_replicas = 0;
+
+DROP TABLE IF EXISTS t_cse_dim;
+DROP TABLE IF EXISTS t_cse_fact;
+
+CREATE TABLE t_cse_dim (k UInt32, y UInt32) ENGINE = MergeTree ORDER BY k SETTINGS auto_statistics_types = 'basic, uniq_v2';
+CREATE TABLE t_cse_fact (k UInt32, v UInt32) ENGINE = MergeTree ORDER BY tuple() SETTINGS auto_statistics_types = 'basic, uniq_v2';
+INSERT INTO t_cse_dim SELECT number, number % 100 FROM numbers(10000);
+INSERT INTO t_cse_fact SELECT number % 10000, number FROM numbers(100000);
+
+SELECT 'without the constant column';
+SELECT replaceRegexpAll(explain, '^[│ ]+', '') FROM (
+    EXPLAIN SELECT sum(v) FROM (SELECT f.v AS v, d.y AS y FROM t_cse_fact AS f INNER JOIN t_cse_dim AS d ON f.k = d.k) WHERE y = 1
+) WHERE explain LIKE '%rows estimated%';
+
+SELECT 'UNION ALL branch selected by its constant';
+SELECT replaceRegexpAll(explain, '^[│ ]+', '') FROM (
+    EXPLAIN SELECT sum(v) FROM (
+        SELECT f.v AS v, d.y AS y, 'a' AS tag FROM t_cse_fact AS f INNER JOIN t_cse_dim AS d ON f.k = d.k
+        UNION ALL
+        SELECT f.v AS v, d.y AS y, 'b' AS tag FROM t_cse_fact AS f INNER JOIN t_cse_dim AS d ON f.k = d.k
+    ) WHERE tag = 'a' AND y = 1
+) WHERE explain LIKE '%rows estimated%';
+
+SELECT 'materialized constants compared with constants';
+SELECT replaceRegexpAll(explain, '^[│ ]+', '') FROM (
+    EXPLAIN SELECT sum(v) FROM t_cse_fact AS f INNER JOIN (SELECT k FROM t_cse_dim WHERE y = 1 AND materialize(5) > 3) AS d ON f.k = d.k
+) WHERE explain LIKE '%Right: rows estimated%';
+SELECT replaceRegexpAll(explain, '^[│ ]+', '') FROM (
+    EXPLAIN SELECT sum(v) FROM t_cse_fact AS f INNER JOIN (SELECT k FROM t_cse_dim WHERE y = 1 AND materialize(5) < 3) AS d ON f.k = d.k
+) WHERE explain LIKE '%Right: rows estimated%';
+
+SELECT sum(v) FROM (
+    SELECT f.v AS v, d.y AS y, 'a' AS tag FROM t_cse_fact AS f INNER JOIN t_cse_dim AS d ON f.k = d.k
+    UNION ALL
+    SELECT f.v AS v, d.y AS y, 'b' AS tag FROM t_cse_fact AS f INNER JOIN t_cse_dim AS d ON f.k = d.k
+) WHERE tag = 'a' AND y = 1;
+
+DROP TABLE t_cse_dim;
+DROP TABLE t_cse_fact;
```

