+size_t limitReadToRequestMap(const std::optional<ByteRangeSet> & request_map, size_t offset, size_t size)
+{
+    if (!request_map || request_map->empty() || size == 0)
+        return size;
+
+    const auto & ranges = request_map->ranges();
+    const size_t window_end = offset + size;
+    /// The ranges are disjoint and sorted, so this is the first range that begins at or after the end of the window.
+    auto it = std::partition_point(ranges.begin(), ranges.end(), [&](const ByteRange & range) { return range.offset < window_end; });
+    if (it == ranges.begin())
+        return size;
+
+    const size_t end = std::prev(it)->end();
+    if (end <= offset)
+        return size;
+
+    return std::min(size, end - offset);
+}
+
+
+void assignRequestMap(std::optional<ByteRangeSet> & request_map, ByteRangeSet ranges, size_t buffer_size)
+{
+    if (ranges.ranges().capacity() * sizeof(ByteRange) <= buffer_size)
+        request_map = std::move(ranges);
+    else
+        request_map.reset();
+}
+
+
+void ReadBufferFromFileDescriptor::setRequestMap(ByteRangeSet ranges)
+{
+    assignRequestMap(request_map, std::move(ranges), internal_buffer.size());
+}
