+void MergeTreeReaderStream::announceReadRequestMapAt(size_t mark)
+{
+    /// Enough for the ranges within reach of a read, bounds the work of one seek.
+    static constexpr size_t max_announced_ranges = 64;
+
+    const auto & ranges = *request_map;
+    /// The ranges of a map are disjoint and sorted, this is the first one that ends after `mark`.
+    auto it = std::partition_point(ranges.begin(), ranges.end(), [&](const MarkRange & range) { return range.end <= mark; });
+    const size_t index = it - ranges.begin();
+
+    /// The announced ranges already contain every range that the reads from here until the next seek can reach.
+    if (index >= announced_ranges_begin && index < announced_ranges_end)
+        return;
+
+    announced_ranges_begin = index;
+    announced_ranges_end = index;
+
+    ByteRangeSet file_ranges;
+    std::optional<size_t> left;
+    if (it != ranges.end() && it->begin <= mark)
+        left = getLeftOffset(mark);
+
+    /// A read outside the map, or in a stream whose marks do not delimit what it reads, fills whole buffers.
+    if (!left)
+    {
+        data_buffer->setRequestMap(std::move(file_ranges));
+        return;
+    }
+
+    /// Every range that begins less than a buffer after the end of the previous one can be reached by one read. A read never
+    /// ends at an announced range that is followed by such a range, so a read is only shortened when the next byte it
+    /// would need is farther than its buffer, and the number of reads does not grow.
+    size_t right = getRightOffset(std::min(it->end, marks_count));
+    while (true)
+    {
+        if (right > *left)
+            file_ranges.add({*left, right - *left});
+        ++it;
+        if (it == ranges.end())
+            break;
+
+        if (static_cast<size_t>(it - ranges.begin()) - index == max_announced_ranges)
+        {
+            /// Do not end the reads at the last announced range: the ranges after it are not announced.
+            if (file_size > right)
+                file_ranges.add({right, file_size - right});
+            break;
+        }
+
+        left = getLeftOffset(it->begin);
+        if (!left || *left >= right + local_read_buffer_size)
+            break;
+        right = std::max(right, getRightOffset(std::min(it->end, marks_count)));
+    }
+
+    announced_ranges_end = it - ranges.begin();
+    data_buffer->setRequestMap(std::move(file_ranges));
+}
+
