```diff
diff --git a/src/Columns/ColumnSparse.cpp b/src/Columns/ColumnSparse.cpp
index 6b1bb045389..fbdc9ceb535 100644
--- a/src/Columns/ColumnSparse.cpp
+++ b/src/Columns/ColumnSparse.cpp
@@ -344,6 +344,68 @@ void ColumnSparse::rollback(const ColumnCheckpoint & checkpoint)
     getOffsetsData().resize_assume_reserved(nested.size - 1);
 }

+namespace
+{
+
+/// Counts the rows a filter keeps before rows visited in ascending order, along 64-row words of the
+/// filter's bitmask: the count before a row is the popcount of the words before it plus the popcount of
+/// its own word below it.
+class FilterWordsCursor
+{
+public:
+    FilterWordsCursor(const UInt8 * filt_, size_t size_) : filt(filt_), size(size_), bits(loadWord(0)) {}
+
+    /// The number of kept rows before `row`, and whether `row` itself is kept. `row` must not decrease
+    /// between calls.
+    std::pair<size_t, bool> seek(size_t row)
+    {
+        const size_t row_word = row / 64;
+        if (row_word != word)
+        {
+            /// The rest of the current word, then the whole words before the row's word in one go:
+            /// a long run of default rows costs one call, as before.
+            kept_before_word += std::popcount(bits);
+            if (row_word > word + 1)
+                kept_before_word += countBytesInFilter(filt, (word + 1) * 64, row_word * 64);
+            word = row_word;
+            bits = loadWord(word);
+        }
+        const UInt64 row_bit = UInt64(1) << (row % 64);
+        return {kept_before_word + std::popcount(bits & (row_bit - 1)), (bits & row_bit) != 0};
+    }
+
+    /// The number of rows the whole filter keeps.
+    size_t countAll() const
+    {
+        const size_t next_word_begin = (word + 1) * 64;
+        size_t res = kept_before_word + std::popcount(bits);
+        if (next_word_begin < size)
+            res += countBytesInFilter(filt, next_word_begin, size);
+        return res;
+    }
+
+private:
+    UInt64 loadWord(size_t w) const
+    {
+        const size_t begin = w * 64;
+        if (begin + 64 <= size)
+            return bytes64MaskToBits64Mask(filt + begin);
+
+        UInt64 res = 0;
+        for (size_t i = begin; i < size; ++i)
+            res |= static_cast<UInt64>(filt[i] != 0) << (i - begin);
+        return res;
+    }
+
+    const UInt8 * filt;
+    size_t size;
+    size_t word = 0;
+    size_t kept_before_word = 0;
+    UInt64 bits;
+};
+
+}
+
