+#!/usr/bin/env bash
+# Tags: no-fasttest
+# Bit-packed dictionary indexes of every width up to 18 bits, and definition and repetition levels,
+# decode to the same values that were written, also when blocks end inside a bit-packed run.
+
+CURDIR=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
+# shellcheck source=../shell_config.sh
+. "$CURDIR"/../shell_config.sh
+
+FILE="${CLICKHOUSE_TMP}/${CLICKHOUSE_TEST_UNIQUE_NAME}.parquet"
+AGG="sum(cityHash64(x)), sum(cityHash64(y)), sum(cityHash64(z)), count()"
+
+for k in $(seq 1 18); do
+    m=$((1 << k))
+    q="SELECT
+            toUInt32(if(number % 1000 < 300, intDiv(number, 97) % 5, intHash32(number) % $m)) AS x,
+            if(number % 13 = 0, NULL, toUInt16(intHash32(number + 1) % $m)) AS y,
+            arrayMap(i -> toUInt32(intHash32(number * 7 + i) % $m), range(number % 4)) AS z
+        FROM numbers(200000)"
+    $CLICKHOUSE_LOCAL -q "INSERT INTO FUNCTION file('$FILE') $q SETTINGS output_format_parquet_row_group_size = 100000, engine_file_truncate_on_insert = 1"
+    $CLICKHOUSE_LOCAL -q "
+        SELECT $k,
+            (SELECT ($AGG) FROM file('$FILE') SETTINGS max_block_size = 777) = (SELECT ($AGG) FROM ($q)),
+            (SELECT ($AGG) FROM file('$FILE') PREWHERE x % 3 = 1 SETTINGS max_block_size = 1000) = (SELECT ($AGG) FROM ($q) WHERE x % 3 = 1)"
+done
+
+rm -f "$FILE"
