@@ -330,14 +331,30 @@ Overloaded(Ts...) -> Overloaded<Ts...>;

 static size_t countPassedStats(ColumnPtr values);

+static bool canSplitNullableKey(const DataTypePtr & type)
+{
+    return type->isNullable() && removeNullable(type)->isValueRepresentedByInteger();
+}
+
+/// The null map of a `Nullable` column with at least one NULL, otherwise nullptr.
+static const NullMap * nullMapWithNulls(const IColumn & column)
+{
+    const auto * nullable = checkAndGetColumn<ColumnNullable>(&column);
+    if (!nullable)
+        return nullptr;
+    const auto & null_map = nullable->getNullMapData();
+    return memoryIsZero(null_map.data(), 0, null_map.size()) ? nullptr : &null_map;
+}
+
 template <bool negate>
 ExactSetRuntimeFilter<negate>::ExactSetRuntimeFilter(
     const DataTypePtr & filter_column_target_type_, UInt64 bytes_limit_, UInt64 exact_values_limit_)
     : filter_column_target_type(filter_column_target_type_)
     , argument_can_have_nulls(hasTypeThatCanContainNulls(filter_column_target_type_))
+    , split_nullable_key(canSplitNullableKey(filter_column_target_type_))
     , bytes_limit(bytes_limit_)
     , exact_values_limit(exact_values_limit_)
-    , lookup_state(Many{std::make_shared<Set>(SizeLimits{}, -1, argument_can_have_nulls)})
+    , lookup_state(Many{std::make_shared<Set>(SizeLimits{}, -1, argument_can_have_nulls && !split_nullable_key)})
 {
     ColumnsWithTypeAndName set_header = {ColumnWithTypeAndName(filter_column_target_type_, String())};
     getExactValues().setHeader(set_header);
@@ -372,9 +389,16 @@ void ExactSetRuntimeFilter<negate>::insert(ColumnPtr values)
         return;

     auto & set = getExactValues();
+    /// Without `transform_null_in` the set skips NULL keys; remember one so that NULL still matches NULL.
+    if (split_nullable_key && !has_null_key && nullMapWithNulls(*values->convertToFullColumnIfConst()))
+        has_null_key = true;
     set.insertFromColumns({values});
-    const size_t set_bytes = bound_key_bytes ? set.getSetElementsBytes() : set.getTotalByteCount();
-    is_full = set.getTotalRowCount() > exact_values_limit || set_bytes > bytes_limit;
+    /// Count the NULL key and the null map as if they were in the set: the limits and the transported state are the same as for a `Nullable` set.
+    const size_t null_keys = has_null_key ? 1 : 0;
+    size_t set_bytes = bound_key_bytes ? set.getSetElementsBytes() : set.getTotalByteCount();
+    if (split_nullable_key && bound_key_bytes)
+        set_bytes += set.getTotalRowCount() + null_keys;
+    is_full = set.getTotalRowCount() + null_keys > exact_values_limit || set_bytes > bytes_limit;
 }

 template <bool negate>
@@ -388,9 +412,9 @@ void ExactSetRuntimeFilter<negate>::finishInsert()
     is_finished = true;

     /// If the set is empty just return a constant false column.
-    if (set.getTotalRowCount() == 0)
