     {
-        lookup_state = Empty{set.getSetElements().front()};
+        lookup_state = Empty{valuesOfTargetType(set.getSetElements().front())};
         return;
     }

@@ -448,7 +472,21 @@ ColumnPtr ExactSetRuntimeFilter<negate>::find(const ColumnWithTypeAndName & valu
                 if (!many.exact_values)
                     throw Exception(ErrorCodes::LOGICAL_ERROR, "Runtime filter exact values are not available");

-                return many.exact_values->execute({values}, negate);
+                ColumnPtr result = many.exact_values->execute({values}, negate);
+                if (!has_null_key)
+                    return result;
+
+                /// The set skipped the NULL key, and a NULL argument is not in it: give such rows the result of a member.
+                ColumnPtr full_values = values.column->convertToFullColumnIfConst();
+                const NullMap * null_map = nullMapWithNulls(*full_values);
+                if (!null_map)
+                    return result;
+                auto mutable_result = IColumn::mutate(std::move(result));
+                auto & result_data = assert_cast<ColumnUInt8 &>(*mutable_result).getData();
+                for (size_t row = 0; row < result_data.size(); ++row)
+                    if ((*null_map)[row])
