 }

+template <bool negate>
+ColumnPtr ExactSetRuntimeFilter<negate>::valuesOfTargetType(ColumnPtr set_elements) const
+{
+    if (!split_nullable_key)
+        return set_elements;
+
+    /// The set keeps the nested values; callers expect the key type, with the NULL key if one was inserted.
+    auto values = IColumn::mutate(makeNullable(set_elements));
+    if (has_null_key)
+        values->insertDefault();
+    return values;
+}
